CREATE OR ALTER PROCEDURE [dbo].[SP_RemoveRoleFromUser] @UserId INT, @RoleName NVARCHAR(50) AS BEGIN SET NOCOUNT OFF; DECLARE @RoleId INT SELECT @RoleId = RoleId FROM ROLES WHERE RoleName = @RoleName IF @RoleId IS NOT NULL BEGIN DELETE FROM USERROLES WHERE UserId = @UserId AND RoleId = @RoleId END END